-- Storefront fully-dynamic round (2026-11-13, Part A): reset seeded fake
-- defaults on CmsPage template rows (P0 — live clients have wrong info indexed).
--
-- RULE: a row is reset ONLY when its stored `config` still equals, exactly
-- (jsonb equality), the known fake-default snapshot that ensureTemplatePages()
-- seeded from template-pages.ts at e62db4be. Rows an admin genuinely edited —
-- or rows whose config was migrated from live SystemSetting values on first
-- creation (about story, FAQ items, contact details, shipping sections) —
-- differ from the snapshot and are left completely untouched. No row is ever
-- blanked on a guess.
--
-- SAFETY: data-only migration (no DDL, no DELETE, no DROP). Row-by-row
-- PL/pgSQL loop; each row's UPDATE runs inside its own BEGIN/EXCEPTION
-- block, so one divergent row can never fail the whole migration — on any
-- error the row is left exactly as it was (preserve-verbatim fallback) and
-- the failure is logged with RAISE NOTICE. A missing row (page not seeded
-- yet) is skipped: ensureTemplatePages() seeds it empty on the next boot.
-- The codebase has no probe_ddl convention (see 20261113160000 migration
-- header); the per-row exception guard above is the safety mechanism for
-- this change.
-- Rollback: restore the affected rows from backup — this migration only
-- overwrites rows whose config still equals a known fake snapshot, listed
-- in the NOTICE output.

DO $cleanup$
DECLARE
  snap jsonb;
  target RECORD;
  reset_count integer := 0;
  skipped_count integer := 0;
  missing_count integer := 0;
BEGIN
  FOR snap IN SELECT * FROM jsonb_array_elements($json$[{"key":"careers","slug":"careers","old":{"hero":{"title":"WE ARE HIRING.","subtitle":"Join a team that cares about health, authenticity, and the growth of Bangladeshi agriculture.","image":""},"jobs":[{"title":"Senior Food Quality Inspector","department":"Quality Control","location":"Dhaka (Mirpur Hub)","type":"Full-time","salary":"৳ 45,000 - 60,000","description":""},{"title":"Supply Chain Coordinator","department":"Logistics","location":"Gazipur Warehouse","type":"Full-time","salary":"৳ 35,000 - 45,000","description":""},{"title":"Content Writer (Food & Health)","department":"Marketing","location":"Remote / Hybrid","type":"Part-time / Contract","salary":"Competitive","description":""},{"title":"Customer Success Lead","department":"Operations","location":"Dhaka","type":"Full-time","salary":"৳ 30,000 - 40,000","description":""}],"benefits":["Health Insurance","Performance Bonus","Learning Subsidies","Flexible Hours"],"application":{"email":"","ctaText":"Send Spontaneous CV"}},"new":{"hero":{"title":"","subtitle":"","image":""},"jobs":[],"benefits":[],"application":{"email":"","ctaText":"Send Spontaneous CV"}}},{"key":"about","slug":"about","old":{"story":"Started with a mission to bring excellence in every interaction.\n\nStore was born from a simple realization: the market lacked high-quality, reliable technology and household solutions. We wanted to bridge the gap between innovation and consumer needs.\n\nOur journey began in 2024 with a vision to redefine reliability. Today, we have grown into a multi-vertical platform serving thousands of customers across the nation.\n\nEvery solution we offer goes through extensive testing. We don't just provide products; we provide confidence.","values":[{"title":"Uncompromising Tech","description":"We leverage the latest engineering standards to ensure high-performance reliability."},{"title":"Precision Focused","description":"Eliminating inefficiencies to ensure our customers get the best value and accuracy."},{"title":"Innovation Driven","description":"Your needs drive our R&D. We build what the future requires today."}],"image":""},"new":{"story":"","tagline":"","values":[],"image":""}},{"key":"company","slug":"company","old":{"name":"Store Limited","registration":"C-182394/2021","certifications":"BSTI Certified","teamSize":"150+ Experts","ceoName":"Mahmud Riaz","established":"2024","philosophy":"At Store, we believe that transparency is the bedrock of trust. From the early stages of development to the final product delivery, we manage every step with integrity.","vision":"Empowering millions through cutting-edge technology and reliable services.","impact":"Simplifying complex technology for the modern Bangladeshi household.","image":""},"new":{"name":"","registration":"","certifications":"","teamSize":"","ceoName":"","established":"","tagline":"","philosophy":"","vision":"","impact":"","image":""}},{"key":"faq","slug":"faq","old":{"items":[{"question":"How do I place an order?","answer":"You can easily place an order through our website by adding items to your cart and proceeding to checkout."},{"question":"What are the payment methods available?","answer":"We accept multiple payment methods including Cash on Delivery (COD), Mobile Banking, and Credit/Debit Cards."},{"question":"How long does delivery take?","answer":"Inside Dhaka, delivery usually takes 1-2 business days. Outside Dhaka, it may take 3-5 business days."},{"question":"What is your return policy?","answer":"If you receive a damaged or incorrect product, you can request a return within 3 days of receiving the order."},{"question":"Are your products authentic?","answer":"Yes, 100% authentic. We carefully source all our products from verified suppliers."},{"question":"How can I track my order?","answer":"You can track your order by entering your order ID or mobile number on the Track Order page."}]},"new":{"items":[]}},{"key":"contact","slug":"support","old":{"phone":"","email":"","address":"","whatsapp":"","hours":[{"days":"Saturday - Thursday","time":"10:00 AM - 10:00 PM"},{"days":"Friday","time":"3:00 PM - 10:00 PM"}]},"new":{"phone":"","email":"","address":"","whatsapp":"","hours":[]}},{"key":"stores","slug":"stores","old":{"stores":[{"name":"Store Warehouse • Dhaka","address":"Level 6, Block D, Shop 63-64, Bashundhara City Shopping Mall, Dhaka","phone":"","hours":"Sat - Thu: 9 AM - 9 PM","mapLink":"https://maps.app.goo.gl/mT4GwfLr9AE6SFqS8","comingSoon":false},{"name":"Chittagong Store","address":"We are expanding! Our second location is coming soon to Chittagong. Stay tuned for updates.","phone":"","hours":"","mapLink":"","comingSoon":true},{"name":"Sylhet Store","address":"We are expanding! Our third location is coming soon to Sylhet. Stay tuned for updates.","phone":"","hours":"","mapLink":"","comingSoon":true}]},"new":{"stores":[]}},{"key":"delivery-areas","slug":"delivery-areas","old":{"areas":[{"zone":"Inside Dhaka","areas":["Gulshan","Banani","Uttara","Mirpur","Mohammadpur","Dhanmondi","Motijheel","Farmgate","Bashundhara","Baridhara"],"charge":"Free","deliveryTime":"24-48 hours"},{"zone":"Outside Dhaka","areas":["Chittagong City","Sylhet City","Rajshahi City","Khulna City","Barisal City","Rangpur City","Mymensingh City"],"charge":"৳100-200","deliveryTime":"3-5 business days"},{"zone":"Other Districts","areas":["All district headquarters across Bangladesh"],"charge":"৳150-300","deliveryTime":"5-7 business days"}],"freeDeliveryMin":0},"new":{"areas":[],"freeDeliveryMin":0}},{"key":"terms-conditions","slug":"terms-conditions","old":{"sections":[{"heading":"1. Acceptance of Terms","body":"FIXED PLUS LTD provides its service to you, subject to the following Terms of Service, which may be updated by us from time to time without notice to you. You can review the most current version of the Terms of Service at any time on this page."},{"heading":"2. Product Authenticity","body":"We guarantee the authenticity of our signature items including pure honey, ghee, and organic oils. However, as these are natural products, seasonal variations in color, texture, and taste are normal and do not qualify as defects."},{"heading":"3. Use of Website","body":"You may use the website for personal, non-commercial purposes only. Any unauthorized use of automated systems or software to extract data from this website for commercial purposes ('screen scraping') is strictly prohibited."},{"heading":"Termination of Service","body":"We reserve the right to refuse service to anyone for any reason at any time. We may also, in our sole discretion, change or discontinue any aspect, service or feature of the website, including, but not limited to, content, hours of availability, and equipment needed for access or use."}]},"new":{"intro":"","sections":[]}},{"key":"privacy-policy","slug":"privacy-policy","old":{"sections":[{"heading":"Data Collection","body":"We only collect essential information needed to fulfill your orders: name, shipping address, mobile number, and email. We do not store sensitive payment details like credit card numbers; these are handled by secured 3rd party gateways."},{"heading":"Usage Disclosure","body":"Your data is primarily used to process transactions, send delivery updates, and occasionally inform you about new products or offers. We never sell your personal information to third-party marketing agencies."},{"heading":"Security Architecture","body":"Our platform uses industry-standard SSL encryption for all data transfers. We conduct periodic security audits to ensure your data remains protected against unauthorized access or breaches."},{"heading":"User Rights","body":"You have the right to request access to the personal data we hold about you at any time.\n\nYou may request the deletion of your account and all associated personal data from our servers.\n\nYou can opt-out of marketing communications by clicking 'Unsubscribe' in our emails.\n\nIf you have any privacy concerns, contact our Data Privacy Officer via email."}]},"new":{"intro":"","sections":[]}},{"key":"refund-policy","slug":"refund-policy","old":{"sections":[{"heading":"Eligibility for Refund","body":"To be eligible for a refund, the product must be in the same condition that you received it, unworn or unused, with tags, and in its original packaging. You'll also need the receipt or proof of purchase."},{"heading":"Reason for Refund","body":"Received a damaged product upon delivery.\n\nReceived a product that is past its expiration date.\n\nReceived the wrong item entirely.\n\nThe quality of the product does not match the description provided."},{"heading":"Refund Timeline","body":"Once we receive and inspect your return, we will notify you of the approval or rejection of your refund. If approved, the refund will be processed within 5-7 business days through your original payment method (bKash, Nagad, or Bank Transfer)."}],"contactEmail":""},"new":{"intro":"","sections":[],"notice":{"title":"","body":""},"contactEmail":""}},{"key":"exchange-policy","slug":"exchange-policy","old":{"sections":[{"heading":"Request Exchange","body":"Contact our support within 24 hours of delivery to initiate the process."},{"heading":"Return Shipping","body":"Our courier will pick up the item or you can ship it back to our hub."},{"heading":"Quality Check","body":"We inspect the returned item to ensure it's in original condition."},{"heading":"Original Packaging","body":"The item must be returned in its original Store packaging."},{"heading":"Proof of Purchase","body":"A valid order ID or paper invoice must be presented."},{"heading":"Non-Food Items","body":"Food items can only be exchanged if damaged; non-food items follow standard rules."},{"heading":"Shipping Costs","body":"Standard shipping charges apply for exchanges unless the error was on our part."}]},"new":{"intro":"","quote":"","sections":[]}},{"key":"shipping-policy","slug":"shipping-policy","old":{"sections":[{"heading":"","body":"At Store, we strive to deliver your orders as quickly and safely as possible."},{"heading":"Processing Time","body":"Orders are processed within 24 hours of placement (excluding Fridays and public holidays)."},{"heading":"Delivery Timeframes","body":"Inside Dhaka: 24-48 hours\n\nOutside Dhaka (City areas): 3-5 business days\n\nOther districts: 5-7 business days"},{"heading":"Shipping Charges","body":"Free shipping on orders over ৳5,000\n\nInside Dhaka: ৳60 flat rate\n\nOutside Dhaka: ৳100-300 depending on location"},{"heading":"Order Tracking","body":"Once shipped, you will receive a tracking ID via SMS to track your order."}],"deliveryCharge":60,"freeDeliveryMin":5000},"new":{"intro":"","sections":[],"deliveryCharge":0,"freeDeliveryMin":0}},{"key":"download","slug":"download","old":{"androidUrl":"","iosUrl":"","heading":"Get the Store App","description":"Install our app for a faster, more convenient shopping experience. Access exclusive deals, track orders in real-time, and enjoy seamless checkout — right from your phone.","image":"","features":["Faster Checkout","Order Tracking","Secure & Private"]},"new":{"androidUrl":"","iosUrl":"","heading":"","description":"","image":"","features":[],"qrCodeUrl":"","version":"","apkUrl":""}}]$json$::jsonb) LOOP
    SELECT id, config INTO target
      FROM "CmsPage"
     WHERE slug = snap ->> 'slug'
       AND "templateKey" = snap ->> 'key';

    IF NOT FOUND THEN
      missing_count := missing_count + 1;
      RAISE NOTICE 'cms fake-defaults cleanup: % not seeded yet, skipped', snap ->> 'slug';
      CONTINUE;
    END IF;

    IF target.config IS NULL OR (target.config)::jsonb IS DISTINCT FROM (snap -> 'old') THEN
      skipped_count := skipped_count + 1;
      RAISE NOTICE 'cms fake-defaults cleanup: % edited or migrated, left untouched', snap ->> 'slug';
      CONTINUE;
    END IF;

    BEGIN
      UPDATE "CmsPage"
         SET config = (snap -> 'new')::jsonb,
             "updatedAt" = now()
       WHERE id = target.id;
      reset_count := reset_count + 1;
      RAISE NOTICE 'cms fake-defaults cleanup: reset % to neutral empty defaults', snap ->> 'slug';
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'cms fake-defaults cleanup: FAILED to reset % (left untouched): %', snap ->> 'slug', SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE 'cms fake-defaults cleanup: done — reset=%, skipped=%, missing=%', reset_count, skipped_count, missing_count;
END
$cleanup$;
